@Override public void onTracksChanged(Tracks tracks){
  int trackCount=0;
  if (tracks.isTypeSelected(C.TRACK_TYPE_AUDIO)) {
    trackCount++;
  }
  if (tracks.isTypeSelected(C.TRACK_TYPE_VIDEO)) {
    trackCount++;
  }
  if (trackCount > 0) {
    assetLoaderListener.onTrackCount(trackCount);
    try {
      player.play();
    } catch (IllegalStateException e) {
      assetLoaderListener.onError(ExportException.createForAssetLoader(e, ERROR_CODE_FAILED_RUNTIME_CHECK));
    }
  }
  else {
    assetLoaderListener.onError(ExportException.createForAssetLoader(new IllegalStateException("The asset loader has no track to output."),ERROR_CODE_FAILED_RUNTIME_CHECK));
  }
}
